import 'dart:math';
import 'package:supabase_flutter/supabase_flutter.dart';
class NotifHookSettings{const NotifHookSettings({required this.enabled,required this.endpoint,required this.apiKey,required this.midtrans,required this.xendit});final bool enabled,midtrans,xendit;final String endpoint,apiKey;factory NotifHookSettings.fromMap(Map<String,dynamic> r)=>NotifHookSettings(enabled:(r['enabled'] as bool?)??true,endpoint:(r['endpoint']??'') as String,apiKey:(r['api_key']??'') as String,midtrans:(r['source_midtrans'] as bool?)??true,xendit:(r['source_xendit'] as bool?)??true);}
class NotifHookRepository{final SupabaseClient _client=Supabase.instance.client;Future<NotifHookSettings?> load(String businessId)async{final r=await _client.from('irkop_cell_notifhook_settings').select().eq('business_id',businessId).maybeSingle();return r==null?null:NotifHookSettings.fromMap(Map<String,dynamic>.from(r));}Future<void> save({required String businessId,required bool enabled,required String endpoint,required String apiKey,required bool midtrans,required bool xendit})=>_client.from('irkop_cell_notifhook_settings').upsert({'business_id':businessId,'enabled':enabled,'endpoint':endpoint.trim(),'api_key':apiKey,'source_midtrans':midtrans,'source_xendit':xendit,'updated_at':DateTime.now().toUtc().toIso8601String()},onConflict:'business_id');String generateKey(){final r=Random.secure();const chars='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';return 'irk_${List.generate(32,(_)=>chars[r.nextInt(chars.length)]).join()}';}}
